#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> a;
    for (int i = 1; i <= 3; i++) {
        a.push_back(i);
    }

    int* before = a.data();
    vector<int> b = move(a);

    cout << b.size() << endl;
    cout << a.size() << endl;
    cout << (b.data() == before ? "同一间" : "换了间") << endl;
    return 0;
}

